import {readFile,writeFile,copyFile,stat} from 'node:fs/promises';
import {spawnSync} from 'node:child_process';
import {decryptIssue} from './voice-bridge.mjs';
import {compileVoiceAutomation} from './voice-automation-request.mjs';
import {extractCompleteVoiceScript,planVoices,digest} from './voice-script.mjs';
import {VOICE_REVIEW_CATALOG,VOICE_REVIEW_RETIRED} from '../src/voice-review-catalog.js';
import {VOICE_MANIFEST} from '../src/voice-manifest.js';
import {voiceReviewPublishReport} from '../src/voice-review-release.js';
const required='voice-20261027-ash-three-01',failedRun='40450696535';
const folder='.local/recovery-artifact/';
const json=async p=>JSON.parse(await readFile(p,'utf8'));
const ledger=await json('config/voice-automation-runs.json'),receipt=ledger.runs[required];
if(!receipt||receipt.status!=='started'||String(receipt.workflowRun)!==failedRun||receipt.recordings!==3)throw Error('Do not alter a mismatching started receipt');
const key=process.env.VOICE_BRIDGE_PRIVATE_KEY?.replace(/\\n/g,'\n');
if(!key)throw Error('Private key unavailable');
const token=process.env.GITHUB_TOKEN;
const response=await fetch('https://api.github.com/repos/Alicetel-u/FeralLife/issues/22',{headers:{Authorization:'Bearer '+token,Accept:'application/vnd.github+json'}});
if(!response.ok)throw Error('Unable to inspect original owner issue');
const issue=await response.json();
if(issue.title!=='[Voice Bridge] repair'||issue.user?.login!=='Alicetel-u')throw Error('Unexpected recovery source issue');
const request=decryptIssue(issue.body,key);
if(request.requestId!==required)throw Error('Request ID mismatch');
const oldLedger=structuredClone(ledger);delete oldLedger.runs[required];
const ids=await json('config/voice-ids.json'),config=await json('config/voice-performance.json'),pronunciations=(await json('config/voice-pronunciation-issues.json')).issues,repairs=await json('config/voice-repairs.json');
const compiled=compileVoiceAutomation(request,{catalog:VOICE_REVIEW_CATALOG,retired:VOICE_REVIEW_RETIRED,script:extractCompleteVoiceScript(),ids,config,pronunciations,repairs,ledger:oldLedger});
if(compiled.requestDigest!==receipt.requestDigest||compiled.planId!==receipt.planId||compiled.count!==3)throw Error('Immutable original request differs from receipt');
const plan=await json(folder+'.local/voice-plan.json'),journal=await json(folder+'.local/voice-journal.json');
if(plan.planId!==receipt.planId||plan.rows.length!==3||Object.keys(journal).length!==3)throw Error('Artifact plan/journal mismatch');
const planned=planVoices(extractCompleteVoiceScript().filter(r=>compiled.targets.includes(r.lineKey)),ids,config,pronunciations,compiled.nextRepairs.lines);
if(planned.length!==3||digest(planned.map(r=>({source:r.source,hash:r.hash})))!==plan.planId)throw Error('Recomputed plan mismatch');
const manifest=structuredClone(VOICE_MANIFEST);
for(const row of plan.rows){
 const actual=planned.find(r=>r.lineKey===row.lineKey);
 const rule=compiled.nextRepairs.lines.find(r=>r.speaker===row.speaker&&r.text===row.text);
 if(!actual||actual.hash!==row.hash||actual.voiceId!==row.voiceId||actual.request.text!==row.spokenInput||JSON.stringify(actual.request.voice_settings)!==JSON.stringify(row.settings)||!rule?.repairComment)throw Error('Actual generated request mismatch: '+row.source);
 if(journal[row.hash]?.status!=='complete'||!journal[row.hash]?.requestId||!journal[row.hash]?.chargedCharacters)throw Error('Missing completed charge record');
 const base=folder+'assets/voices/'+row.hash,source=base+'.mp3',master=base+'.repair.mp3';
 for(const file of [source,master])if((await stat(file)).size<8192)throw Error('Missing or tiny audio: '+file);
 const old=manifest[row.lineKey];if(!old)throw Error('Missing original voice manifest identity');
 const output='assets/voices/'+row.hash;
 await copyFile(source,output+'.mp3');await copyFile(master,output+'.repair.mp3');
 manifest[row.lineKey]={...old,file:output+'.repair.mp3',hash:row.hash,source:row.source,speaker:row.speaker,text:row.text,performance:row.performance,model:config.model,repairReview:true,repairComment:'再生成済み。'+rule.repairComment,audioMastering:{integratedLUFS:-18,truePeakDBTP:-6,tailPaddingSeconds:.25,fadeInSeconds:.004,fadeOutSeconds:.016}};
 delete manifest[row.lineKey].fastFile;
}
await writeFile('config/voice-repairs.json',JSON.stringify(compiled.nextRepairs,null,2)+'\n');
await writeFile('config/voice-review-published.json',JSON.stringify(voiceReviewPublishReport(await json('config/voice-review-published.json'),compiled.report,VOICE_REVIEW_CATALOG),null,2)+'\n');
await writeFile('src/voice-manifest.js','// Generated clips only.\nexport const VOICE_MANIFEST = '+JSON.stringify(manifest,null,2)+';\n');
console.log('Recovered exact three completed recordings from run '+failedRun+'; paid generation API calls: 0');
